with flattened as (select id, plan, currency, explode_outer(tier_limits) as element from price_tiers) select currency, approx_percentile(element, 0.95) as element_p95, percentile_approx(element, array(0.25, 0.5, 0.75)) as element_quartiles, count(distinct plan) as distinct_plans, count(*) as num_rows, count(*) filter (where currency = 'USD') as usd_rows, grouping_id() as grouping_level from flattened group by cube (currency) having approx_percentile(element, 0.95) >= 0;
